echo ""
echo "Archivos aplicados. Pasos siguientes:"
echo "  1) git add backend/prisma/schema.prisma backend/prisma/migrate-fase12-order-status.ts backend/package.json backend/src/modules/orders/orders.routes.ts backend/src/modules/routes/routes.routes.ts frontend/src/pages/planner/PlanificacionTab.tsx frontend/src/pages/OrdersPage.tsx frontend/src/pages/planner/RutasTab.tsx frontend/src/pages/planner/DispatchBoard.tsx"
echo "  2) git commit -m \"feat: fecha visible en Planificador/Rutas/Despacho y ciclo de estado de pedido simplificado (Fase 12)\""
echo "  3) git push"
echo "  4) En Cloud Shell: git pull origin main && npx prisma db push  (SI hace falta esta vez -- cambia el valor por defecto de Order.status)"
echo "  5) Tras el db push, ejecutar UNA VEZ: npm run db:migrate-fase12-order-status --prefix backend  (o: cd backend && npx tsx prisma/migrate-fase12-order-status.ts) -- pasa a Validado los pedidos antiguos que sigan en Recibido. Es idempotente, no pasa nada si se ejecuta mas de una vez."
echo "  6) Verificar que el build/deploy automatico (GitHub Actions) termina en verde."
